   // We wrap the malicious payload in an IIFE so it executes `process.seteuid(42)`,
   // then returns a valid numeric ratio (0.5) to prevent immediate runtime errors,
   // proving that arbitrary code can be injected while maintaining application flow.
   const maliciousRatio = '(function(){ process.seteuid(42); return 0.5; })()';

