    // var code = 'func = ' + self + ';';
    // eval(code);
    // There is zero sanitization or escaping of the `self` argument.
    const maliciousPayload = "process.seteuid(42)";

    // Calling .toFunction() on our crafted string forces the unsafe eval 
    // to execute immediately with our injected system call.
