class Server
    name: pkg.name
    version: pkg.version

    defaults: ->
        port: 8000
        host: '0.0.0.0'
        logs: false
        index: 'index.html'

    constructor: (options={}, @exitCallback)->
        @options = _.extend @defaults(), options

        @_initLogs()
        @_bindCloseEvents()

        @start()

    start: ->
