 * @param path
 * @param modifiers
 */
function collideBasic(arg1: BasicType, arg2: BasicType, path: string, modifiers?: ICollideModifiers): any {
    if (modifiers && modifiers[path]) {
        return modifiers[path](arg1, arg2);
