+ * Returns whether the given node either is or is a child of what is effectively a Kleene star.
+ *
+ * @param {import("regexpp/ast").Node} node
+ * @returns {boolean}
+ */
+function underAStar(node) {
+  if (node.type === "Quantifier" && node.max > 10) {
+    return true;
+  } else if (node.parent) {
