  // code points that are functionally equivalent (e.g., \u0020, \u00A0, \u1680, \u2000-200A, etc.).
  // In older V8/Node.js regex engines, matching a long sequence of these equivalent characters
  // against a trailing non-matching character forces the engine into exhaustive path reconciliation.

  const wsChars = '\x09\x0A\x0B\x0C\x0D\x20\xA0\u1680\u180E\u2000\u2001\u2002\u2003' +
